SourceCode.Declaration:
/// <summary>
/// CB223_PalletRounding
/// Post pricing order optimisation multithread batch task
/// inspired from new class LedgerJournalBatchPost
/// </summary>
class METPostPricingOrderOptimisationService extends METSysOperationService
{
    private guid topPickingProcessId;
    container salesOrderCon;

}

Method.Source:
/// <summary>
/// Returns task service class name.
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METPostPricingOrderOptimisationTaskService);
}

/// <summary>
/// Returns task service class method.
/// </summary>
/// <returns>Task service class method</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METPostPricingOrderOptimisationTaskService, process);
}

/// <summary>
/// Returns caption of the task service class.
/// </summary>
/// <returns>Task service class caption</returns>
protected str getTaskServiceCaption()
{
    return "@MET:PostPricingOrderOptimisation";
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSysOperationTaskDataContract</c>
/// </param>
public void process(METPostPricingOrderOptimisationContract _contract)
{
    METProcMetrics procMetrics = METProcMetrics::construct(METBatchLogOperation::PostPricingOrderOptimisation);
    using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
    {
        this.processInternal(_contract);
        procMetrics.endTrace();
    }

}

/// <summary>
/// This method trigger the Credit check batch job
/// </summary>
/// <param name = "_contract">METPostPricingOrderOptimisationContract class object</param>
public void runCreditCheckBatchJob(METPostPricingOrderOptimisationContract _contract)
{
    METSalesOrderCreditMgmtCheckController  controller;
    METSalesOrderCreditMgmtCheckContract    contract;
    Args                                    args = new Args();

    args.name(classStr(METPostPricingOrderOptimisationController));
    controller  = METSalesOrderCreditMgmtCheckController::construct(args);
    contract    = controller.getDataContractObject();
    contract.parmBundleCount(_contract.parmBundleCount());
    contract.parmIsMainBatchTask(_contract.parmIsMainBatchTask());
    contract.parmThreadCount(_contract.parmThreadCount());
    contract.parmTopPickingProcessId(_contract.parmTopPickingProcessId());
    contract.parmSalesOrderCon(salesOrderCon);
    contract.parmMenuItemName(args.name());

    controller.parmShowDialog(false);
    controller.parmExecutionMode(SysOperationExecutionMode::ScheduledBatch);
    controller.startOperation();
}

/// <summary>Initialise global variables</summary>
public void initialise()
{
    super();

    runAsync = false;

    METPostPricingOrderOptimisationContract contract = dataContract as METPostPricingOrderOptimisationContract;
    Query query = contract.getQuery();

    this.processSalesOrders(query);

}

/// <summary>
/// Initializes the task data contract.
/// </summary>
/// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    METPostPricingOrderOptimisationContract contract = _taskDataContract as METPostPricingOrderOptimisationContract;
    contract.parmTopPickingProcessId(topPickingProcessId);
}

/// <summary>
/// Provides task data contract.
/// </summary>
/// <returns>task data contract</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METPostPricingOrderOptimisationContract();
}

/// <summary>
/// Process sales orders to pallet rounding and quotas from the query and insert SO number in <c>METPostPricingOrderOptimisationQueue</c>
/// </summary>
/// <param name = "_query"><c>Query</c> object</param>
void processSalesOrders(Query _query)
{
    SalesTable st;
    RecordInsertList postPricingOrderOptimisationQueueList;
    #OCCRetryCount

    METPostPricingOrderOptimisationQueue::cleanUpPostSalesOrderCreationProcessingQueue();
    postPricingOrderOptimisationQueueList = new RecordInsertList(tableNum(METPostPricingOrderOptimisationQueue));
    topPickingProcessId = newGuid();
    METProcMetrics procMetrics = METProcMetricsScope::current();

    QueryRun qr = new QueryRun(_query);

    if (procMetrics)
    {
        procMetrics.setTotalCountFromQuery(qr);
        procMetrics.beginTrace('Process started');
        //Or use procMetrics start trace method: pass count & description to set and start the log in one call
    }

    while (qr.next())
    {
        try
        {
            st = qr.get(tableNum(SalesTable));

            this.addToPostPricingOrderOptimisationQueueList(
                    postPricingOrderOptimisationQueueList,
                    st.SalesId);

            if (procMetrics)
            {
                procMetrics.incProcessedCount();
            }
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Error)
        {
            SysInfologEnumerator enumerator = SysInfologEnumerator::newData(infolog.copy(1, infolog.num()));
            SysInfologMessageStruct msgStruct;
            str errorText;

            while (enumerator.moveNext())
            {
                msgStruct = new SysInfologMessageStruct(enumerator.currentMessage());
                errorText += (errorText ? ' | ' : '') + msgStruct.message();
            }

            error(strFmt("@MET:FailedToProcessSO",
                            st.SalesId,
                            errorText));

            // Continue with next sales order
        }
    }

    this.insertIntoTopPickingQueue(postPricingOrderOptimisationQueueList);
}

/// <summary>
/// Adding sales order to process into the RecordInsertList
/// </summary>
/// <param name = "_journalPostQueueList"><c>RecordInsertList</c> object</param>
/// <param name = "_salesId">Sales order number</param>
private void addToPostPricingOrderOptimisationQueueList(RecordInsertList _journalPostQueueList, SalesIdBase _salesId)
{
    METPostPricingOrderOptimisationQueue postRecord;
    postRecord.ProcessId = this.topPickingProcessId;
    postRecord.SalesId = _salesId;

    //Bug312684-Batch jobs for Optimisation completed not finishing - by Narendran
    salesOrderCon += _salesId;
    _journalPostQueueList.add(postRecord);
}

/// <summary>
/// Buld insert from RecordInsertList into <c>METPostPricingOrderOptimisationQueue</c>
/// </summary>
/// <param name = "_postPricingOrderOptimisationQueueList">RecordInsertList to bulk insert</param>
private void insertIntoTopPickingQueue(RecordInsertList _postPricingOrderOptimisationQueueList)
{
    _postPricingOrderOptimisationQueueList.insertDatabase();
}
